/* Fan arrangements by Toshihiko Hayashi, public CPBL MIDI pack (2019/2020). */
window.CPBL_CHEER_MIDI=[];
(async()=>{const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));window.CPBL_CHEER_MIDI=JSON.parse(await new Response(stream).text());window.dispatchEvent(new Event('cheerready'));})().catch(error=>console.warn('Cheer pack unavailable',error));
